```ts
export function ordenarPorDescuento(subtotalCentavos: number, cupones: readonly Cupon[]): Cupon[] {
  return [...cupones].sort(
    (a, b) => calcularDescuento(subtotalCentavos, b) - calcularDescuento(subtotalCentavos, a),
  );
}
